def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

import java.util.*;

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (seen.containsKey(target - nums[i])) return new int[]{seen.get(target - nums[i]), i};
            seen.put(nums[i], i);
        }
        return new int[0];
    }
}

def max_sub_array(nums):
    ans = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        ans = max(ans, cur)
    return ans

class Solution {
    public int maxSubArray(int[] nums) {
        int ans = nums[0], cur = nums[0];
        for (int i = 1; i < nums.length; i++) {
            cur = Math.max(nums[i], cur + nums[i]);
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

def max_area(height):
    left, right, ans = 0, len(height) - 1, 0
    while left < right:
        ans = max(ans, (right-left) * min(height[left], height[right]))
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return ans

class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1, ans = 0;
        while (left < right) {
            ans = Math.max(ans, (right - left) * Math.min(height[left], height[right]));
            if (height[left] < height[right]) left++;
            else right--;
        }
        return ans;
    }
}

def trap(height):
    l, r = 0, len(height)-1
    lm = rm = water = 0
    while l < r:
        if height[l] <= height[r]:
            lm = max(lm, height[l]); water += lm-height[l]; l += 1
        else:
            rm = max(rm, height[r]); water += rm-height[r]; r -= 1
    return water

class Solution {
    public int trap(int[] h) {
        int l = 0, r = h.length - 1, lm = 0, rm = 0, ans = 0;
        while (l < r) {
            if (h[l] <= h[r]) { lm = Math.max(lm, h[l++]); ans += lm - h[l - 1]; }
            else { rm = Math.max(rm, h[r--]); ans += rm - h[r + 1]; }
        }
        return ans;
    }
}

def move_zeroes(nums):
    slow = 0
    for fast, x in enumerate(nums):
        if x != 0:
            nums[slow] = x; slow += 1
    for i in range(slow, len(nums)):
        nums[i] = 0

class Solution {
    public void moveZeroes(int[] nums) {
        int slow = 0;
        for (int x : nums) if (x != 0) nums[slow++] = x;
        while (slow < nums.length) nums[slow++] = 0;
    }
}

class Solution {
    public void merge(int[] a, int m, int[] b, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1;
        while (i >= 0 && j >= 0) a[k--] = a[i] >= b[j] ? a[i--] : b[j--];
        while (j >= 0) a[k--] = b[j--];
    }
}

def remove_duplicates(nums):
    slow = 0
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1; nums[slow] = nums[fast]
    return slow + 1

class Solution {
    public int removeDuplicates(int[] nums) {
        int slow = 0;
        for (int fast = 1; fast < nums.length; fast++)
            if (nums[fast] != nums[slow]) nums[++slow] = nums[fast];
        return slow + 1;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> ans = new ArrayList<>();
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int sum = nums[i] + nums[l] + nums[r];
                if (sum < 0) l++;
                else if (sum > 0) r--;
                else {
                    ans.add(new ArrayList<>(List.of(nums[i], nums[l++], nums[r--])));
                    while (l < r && nums[l] == nums[l - 1]) l++;
                    while (l < r && nums[r] == nums[r + 1]) r--;
                }
            }
        }
        return ans;
    }
}

class Solution {
    public int[] productExceptSelf(int[] nums) {
        int[] ans = new int[nums.length];
        ans[0] = 1;
        for (int i = 1; i < nums.length; i++) ans[i] = ans[i - 1] * nums[i - 1];
        for (int i = nums.length - 1, right = 1; i >= 0; i--) {
            ans[i] *= right;
            right *= nums[i];
        }
        return ans;
    }
}

def length_of_longest_substring(s):
    last={}; left=ans=0
    for right,ch in enumerate(s):
        if ch in last and last[ch]>=left: left=last[ch]+1
        last[ch]=right; ans=max(ans,right-left+1)
    return ans

import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int ans = 0;
        for (int left = 0, right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (last.containsKey(c) && last.get(c) >= left) left = last.get(c) + 1;
            last.put(c, right);
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }
}

def is_valid(s):
    pairs={')':'(',']':'[','}':'{'}; st=[]
    for ch in s:
        if ch in '([{': st.append(ch)
        elif not st or st.pop()!=pairs[ch]: return False
    return not st

import java.util.*;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> st = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(') st.push(')');
            else if (c == '[') st.push(']');
            else if (c == '{') st.push('}');
            else if (st.isEmpty() || st.pop() != c) return false;
        }
        return st.isEmpty();
    }
}

class MinStack:
    def __init__(self): self.st=[]; self.mn=[]
    def push(self,x):
        self.st.append(x); self.mn.append(min(x,self.mn[-1] if self.mn else x))
    def pop(self): self.st.pop(); self.mn.pop()
    def top(self): return self.st[-1]
    def getMin(self): return self.mn[-1]

import java.util.*;

class MinStack {
    private Deque<Long> values = new ArrayDeque<>();
    private Deque<Long> minimums = new ArrayDeque<>();

    public void push(int val) {
        values.push((long) val);
        minimums.push(Math.min((long) val, minimums.isEmpty() ? (long) val : minimums.peek()));
    }

    public void pop() { values.pop(); minimums.pop(); }
    public int top() { return values.peek().intValue(); }
    public int getMin() { return minimums.peek().intValue(); }
}

def next_greater(nums):
    ans=[-1]*len(nums); st=[]
    for i,x in enumerate(nums):
        while st and nums[st[-1]]<x: ans[st.pop()]=x
        st.append(i)
    return ans

import java.util.*;

class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int[] ans = new int[nums.length];
        Arrays.fill(ans, -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < nums.length; i++) {
            while (!st.isEmpty() && nums[st.peek()] < nums[i]) ans[st.pop()] = nums[i];
            st.push(i);
        }
        return ans;
    }
}

def daily_temperatures(T):
    ans=[0]*len(T); st=[]
    for i,x in enumerate(T):
        while st and T[st[-1]]<x: j=st.pop(); ans[j]=i-j
        st.append(i)
    return ans

import java.util.*;

class Solution {
    public int[] dailyTemperatures(int[] t) {
        int[] ans = new int[t.length];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < t.length; i++) {
            while (!st.isEmpty() && t[st.peek()] < t[i]) ans[st.peek()] = i - st.pop();
            st.push(i);
        }
        return ans;
    }
}

def largest_rect(heights):
    hs=heights+[0]; st=[-1]; ans=0
    for i,h in enumerate(hs):
        while st[-1]!=-1 and hs[st[-1]]>=h:
            height=hs[st.pop()]
            ans=max(ans,height*(i-st[-1]-1))
        st.append(i)
    return ans

import java.util.*;

class Solution {
    public int largestRectangleArea(int[] hs) {
        Deque<Integer> st = new ArrayDeque<>();
        st.push(-1);
        int ans = 0;
        for (int i = 0; i <= hs.length; i++) {
            int h = i == hs.length ? 0 : hs[i];
            while (st.peek() != -1 && hs[st.peek()] >= h) {
                int height = hs[st.pop()];
                ans = Math.max(ans, height * (i - st.peek() - 1));
            }
            st.push(i);
        }
        return ans;
    }
}

def decode_string(s):
    cnt=[]; st=[]; cur=''; n=0
    for ch in s:
        if ch.isdigit(): n=n*10+int(ch)
        elif ch=='[': cnt.append(n); st.append(cur); n=0; cur=''
        elif ch==']': cur=st.pop()*cnt.pop()+cur
        else: cur+=ch
    return cur

import java.util.*;

class Solution {
    public String decodeString(String s) {
        Deque<Integer> counts = new ArrayDeque<>();
        Deque<StringBuilder> prefixes = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        for (int i = 0, n = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) n = n * 10 + c - '0';
            else if (c == '[') { counts.push(n); prefixes.push(cur); cur = new StringBuilder(); n = 0; }
            else if (c == ']') {
                StringBuilder next = prefixes.pop();
                for (int k = counts.pop(); k > 0; k--) next.append(cur);
                cur = next;
            } else cur.append(c);
        }
        return cur.toString();
    }
}

from collections import deque
def max_window(nums,k):
    dq=deque(); ans=[]
    for i,x in enumerate(nums):
        while dq and nums[dq[-1]]<=x: dq.pop()
        dq.append(i)
        if dq[0]<=i-k: dq.popleft()
        if i>=k-1: ans.append(nums[dq[0]])
    return ans

import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        int[] ans = new int[nums.length - k + 1];
        for (int i = 0, j = 0; i < nums.length; i++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
            dq.addLast(i);
            if (dq.peekFirst() <= i - k) dq.pollFirst();
            if (i >= k - 1) ans[j++] = nums[dq.peekFirst()];
        }
        return ans;
    }
}

def eval_rpn(tokens):
    st=[]
    for x in tokens:
        if x in '+-*/':
            b=st.pop(); a=st.pop()
            if x=='+': st.append(a+b)
            elif x=='-': st.append(a-b)
            elif x=='*': st.append(a*b)
            else: st.append(int(a/b))
        else: st.append(int(x))
    return st[0]

import java.util.*;

class Solution {
    public int evalRPN(String[] tokens) {
        Deque<Integer> st = new ArrayDeque<>();
        for (String t : tokens) {
            switch (t) {
                case "+" -> st.push(st.pop() + st.pop());
                case "*" -> st.push(st.pop() * st.pop());
                case "-" -> { int b = st.pop(); st.push(st.pop() - b); }
                case "/" -> { int b = st.pop(); st.push(st.pop() / b); }
                default -> st.push(Integer.parseInt(t));
            }
        }
        return st.pop();
    }
}

from collections import defaultdict
def group_anagrams(strs):
    g=defaultdict(list)
    for s in strs: g[tuple(sorted(s))].append(s)
    return list(g.values())

import java.util.*;

class Solution {
    public List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String s : strs) {
            char[] a = s.toCharArray();
            Arrays.sort(a);
            groups.computeIfAbsent(new String(a), k -> new ArrayList<>()).add(s);
        }
        return new ArrayList<>(groups.values());
    }
}

import java.util.*;

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.merge(x, 1, Integer::sum);
        return count.entrySet().stream()
            .sorted(Map.Entry.<Integer,Integer>comparingByValue().reversed())
            .limit(k).mapToInt(Map.Entry::getKey).toArray();
    }
}

def longest_consecutive(nums):
    s=set(nums); ans=0
    for x in s:
        if x-1 not in s:
            y=x
            while y+1 in s: y+=1
            ans=max(ans,y-x+1)
    return ans

import java.util.*;

class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int x : nums) set.add(x);
        int ans = 0;
        for (int x : set) if (!set.contains(x - 1)) {
            int y = x;
            while (set.contains(y + 1)) y++;
            ans = Math.max(ans, y - x + 1);
        }
        return ans;
    }
}

from collections import defaultdict
def subarray_sum(nums,k):
    seen=defaultdict(int); seen[0]=1; p=ans=0
    for x in nums:
        p+=x; ans+=seen[p-k]; seen[p]+=1
    return ans

import java.util.*;

class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);
        int prefix = 0, ans = 0;
        for (int x : nums) {
            prefix += x;
            ans += seen.getOrDefault(prefix - k, 0);
            seen.merge(prefix, 1, Integer::sum);
        }
        return ans;
    }
}

from collections import Counter
def first_unique_char(s):
    freq=Counter(s)
    for i,ch in enumerate(s):
        if freq[ch]==1: return i
    return -1

import java.util.*;

class Solution {
    public int firstUniqChar(String s) {
        int[] count = new int[128];
        for (char c : s.toCharArray()) count[c]++;
        for (int i = 0; i < s.length(); i++) if (count[s.charAt(i)] == 1) return i;
        return -1;
    }
}

def contains_nearby(nums,k):
    last={}
    for i,x in enumerate(nums):
        if x in last and i-last[x]<=k: return True
        last[x]=i
    return False

import java.util.*;

class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (last.containsKey(nums[i]) && i - last.get(nums[i]) <= k) return true;
            last.put(nums[i], i);
        }
        return false;
    }
}

from collections import Counter
def four_sum_count(A,B,C,D):
    ab=Counter(a+b for a in A for b in B)
    return sum(ab[-(c+d)] for c in C for d in D)

import java.util.*;

class Solution {
    public int fourSumCount(int[] a, int[] b, int[] c, int[] d) {
        Map<Integer, Integer> ab = new HashMap<>();
        for (int x : a) for (int y : b) ab.merge(x + y, 1, Integer::sum);
        int ans = 0;
        for (int x : c) for (int y : d) ans += ab.getOrDefault(-(x + y), 0);
        return ans;
    }
}

import random,bisect
class WeightPicker:
    def __init__(self,w):
        self.p=[]; s=0
        for x in w: s+=x; self.p.append(s)
    def pick(self): return bisect.bisect_left(self.p,random.randint(1,self.p[-1]))

import java.util.concurrent.ThreadLocalRandom;

class WeightPicker {
    private int[] prefix;

    public WeightPicker(int[] w) {
        prefix = new int[w.length];
        prefix[0] = w[0];
        for (int i = 1; i < w.length; i++) prefix[i] = prefix[i - 1] + w[i];
    }

    public int pick() {
        int target = ThreadLocalRandom.current().nextInt(1, prefix[prefix.length - 1] + 1);
        int lo = 0, hi = prefix.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (prefix[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null;
        while (head != null) {
            ListNode next = head.next;
            head.next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }
}

class Solution {
    public ListNode middleNode(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }
}

def has_cycle(head):
    slow=fast=head
    while fast and fast.next:
        slow=slow.next; fast=fast.next.next
        if slow is fast: return True
    return False

public class Solution {
    public boolean hasCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }
}

class Solution {
    public ListNode mergeTwoLists(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(), tail = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = a != null ? a : b;
        return dummy.next;
    }
}

def sort_list(head):
    if not head or not head.next: return head
    slow,fast=head,head.next
    while fast and fast.next: slow=slow.next; fast=fast.next.next
    mid=slow.next; slow.next=None
    return merge_lists(sort_list(head),sort_list(mid))

class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;
        ListNode slow = head, fast = head.next;
        while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; }
        ListNode mid = slow.next;
        slow.next = null;
        return merge(sortList(head), sortList(mid));
    }

    private ListNode merge(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(), tail = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = a != null ? a : b;
        return dummy.next;
    }
}

class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode();
        dummy.next = head;
        ListNode slow = dummy, fast = dummy;
        for (int i = 0; i <= n; i++) fast = fast.next;
        while (fast != null) { slow = slow.next; fast = fast.next; }
        slow.next = slow.next.next;
        return dummy.next;
    }
}

import java.util.*;

class Solution {
    public boolean isPalindrome(ListNode head) {
        List<Integer> values = new ArrayList<>();
        for (; head != null; head = head.next) values.add(head.val);
        for (int l = 0, r = values.size() - 1; l < r; l++, r--)
            if (!values.get(l).equals(values.get(r))) return false;
        return true;
    }
}

class Solution {
    public ListNode addTwoNumbers(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(), tail = dummy;
        for (int carry = 0; a != null || b != null || carry > 0; tail = tail.next) {
            int sum = carry + (a != null ? a.val : 0) + (b != null ? b.val : 0);
            carry = sum / 10;
            tail.next = new ListNode(sum % 10);
            if (a != null) a = a.next;
            if (b != null) b = b.next;
        }
        return dummy.next;
    }
}

import java.util.*;

class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;
        Map<Node, Node> copied = new HashMap<>();
        for (Node cur = head; cur != null; cur = cur.next) copied.put(cur, new Node(cur.val));
        for (Node cur = head; cur != null; cur = cur.next) {
            copied.get(cur).next = copied.get(cur.next);
            copied.get(cur).random = copied.get(cur.random);
        }
        return copied.get(head);
    }
}

class LRUCache:
    def __init__(self,cap):
        self.cap=cap; self.m={}; self.head=Node(); self.tail=Node(); self.head.next=self.tail; self.tail.prev=self.head
    def _remove(self,n): n.prev.next=n.next; n.next.prev=n.prev
    def _add(self,n): n.next=self.head.next; n.prev=self.head; self.head.next.prev=n; self.head.next=n
    def get(self,k):
        if k not in self.m: return -1
        n=self.m[k]; self._remove(n); self._add(n); return n.v
    def put(self,k,v):
        if k in self.m: n=self.m[k]; n.v=v; self._remove(n)
        else: n=Node(k,v); self.m[k]=n
        self._add(n)
        if len(self.m)>self.cap: old=self.tail.prev; self._remove(old); del self.m[old.k]

import java.util.*;

class LRUCache {
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(), tail = new Node();

    private static class Node {
        int key, value;
        Node prev, next;
    }

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);
        if (node == null) return -1;
        remove(node); addFirst(node);
        return node.value;
    }

    public void put(int key, int value) {
        Node node = map.get(key);
        if (node != null) { node.value = value; remove(node); }
        else {
            node = new Node(); node.key = key; map.put(key, node);
        }
        node.value = value; addFirst(node);
        if (map.size() > capacity) {
            Node old = tail.prev;
            remove(old); map.remove(old.key);
        }
    }

    private void remove(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    private void addFirst(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
}

def my_pow(x,n):
    if n<0: return 1/my_pow(x,-n)
    ans=1
    while n:
        if n&1: ans*=x
        x*=x; n>>=1
    return ans

def search_rotated(nums,t):
    lo,hi=0,len(nums)-1
    while lo<=hi:
        mid=(lo+hi)//2
        if nums[mid]==t: return mid
        if nums[lo]<=nums[mid]:
            if nums[lo]<=t<nums[mid]: hi=mid-1
            else: lo=mid+1
        else:
            if nums[mid]<t<=nums[hi]: lo=mid+1
