from collections import defaultdict
def accounts_merge(accounts):
    email_id={}; emails=[]
    for acc in accounts:
        for e in acc[1:]:
            if e not in email_id: email_id[e]=len(emails); emails.append(e)
    p=list(range(len(emails)))
    def find(x):
        while p[x]!=x: p[x]=p[p[x]]; x=p[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: p[ra]=rb
    for acc in accounts:
        ids=[email_id[e] for e in acc[1:]]
        for x in ids[1:]: union(ids[0],x)
    groups=defaultdict(set)
    for e,i in email_id.items(): groups[find(i)].add(e)
    owner={email_id[acc[1]]:acc[0] for acc in accounts}
    return [[owner[root]]+sorted(emails) for root,emails in groups.items()]

