            x=self.items.pop(0); self.not_full.notify(); return x

import heapq,time
class FairScheduler:
    def __init__(self): self.heap=[]; self.seq=0; self.usage={}
    def submit(self,task,deadline,user,base_priority):
        self.seq+=1
        fairness=self.usage.get(user,0)*0.001
        heapq.heappush(self.heap,(deadline,base_priority+fairness,self.seq,user,task))
    def next_task(self):
        if not self.heap: return None
        deadline,priority,seq,user,task=heapq.heappop(self.heap)
        self.usage[user]=self.usage.get(user,0)+1
        return task

import java.util.*;

class FairScheduler {
    private static final class Task {
        long deadline, priority, sequence;
        String user, task;
    }

    private final PriorityQueue<Task> heap = new PriorityQueue<>((a,b) -> {
        if (a.deadline != b.deadline) return Long.compare(a.deadline, b.deadline);
        if (a.priority != b.priority) return Long.compare(a.priority, b.priority);
        return Long.compare(a.sequence, b.sequence);
    });
    private long sequence;
    private final Map<String,Long> usage = new HashMap<>();

    public void submit(String task, long deadline, String user, int basePriority) {
        Task item = new Task();
        item.deadline = deadline;
        item.priority = basePriority + usage.getOrDefault(user, 0L) * 1_000L;
        item.sequence = ++sequence;
        item.user = user;
        item.task = task;
        heap.offer(item);
    }

    public String nextTask() {
        Task item = heap.poll();
        if (item == null) return null;
        usage.merge(item.user, 1L, Long::sum);
        return item.task;
    }
}

def sort_colors(nums):
    left=i=0; right=len(nums)-1
    while i<=right:
        if nums[i]==0:
            nums[i],nums[left]=nums[left],nums[i]; left+=1; i+=1
        elif nums[i]==2:
            nums[i],nums[right]=nums[right],nums[i]; right-=1
        else: i+=1
    return nums

class Solution {
