        int left = 0, i = 0, right = nums.length - 1;
        while (i <= right) {
            if (nums[i] == 0) { int t = nums[i]; nums[i++] = nums[left]; nums[left++] = t; }
            else if (nums[i] == 2) { int t = nums[i]; nums[i] = nums[right]; nums[right--] = t; }
            else i++;
        }
    }
}

def count_inversions(nums):
    MOD=10**9+7; a=list(nums)
    def sort(l,r):
        if l>=r: return 0
        m=(l+r)//2; ans=sort(l,m)+sort(m+1,r); tmp=[]; i,j=l,m+1
        while i<=m and j<=r:
            if a[i]<=a[j]: tmp.append(a[i]); i+=1
            else: ans+=m-i+1; tmp.append(a[j]); j+=1
        tmp.extend(a[i:m+1] or a[j:r+1]); a[l:r+1]=tmp; return ans%MOD
    return sort(0,len(a)-1)

class Solution {
    private int[] temp;
    public int countInversions(int[] nums) {
        temp = new int[nums.length];
        return (int) (merge(nums, 0, nums.length - 1) % 1_000_000_007L);
    }
    private long merge(int[] a, int l, int r) {
        if (l >= r) return 0;
        int m = (l + r) / 2, i = l, j = m + 1, k = l;
        long ans = merge(a, l, m) + merge(a, m + 1, r);
        while (i <= m && j <= r) {
            if (a[i] <= a[j]) temp[k++] = a[i++];
            else { ans += m - i + 1; temp[k++] = a[j++]; }
        }
        while (i <= m) temp[k++] = a[i++];
        while (j <= r) temp[k++] = a[j++];
        System.arraycopy(temp, l, a, l, r - l + 1);
        return ans;
    }
}

class Solution {
    public int maximumGap(int[] nums) {
        if (nums.length < 2) return 0;
        int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
        for (int x : nums) { lo = Math.min(lo, x); hi = Math.max(hi, x); }
        if (lo == hi) return 0;
        int n = nums.length, size = Math.max(1, (hi - lo) / (n - 1)), count = (hi - lo) / size + 1;
        int[][] buckets = new int[count][2];
        for (int[] b : buckets) { b[0] = Integer.MAX_VALUE; b[1] = Integer.MIN_VALUE; }
        for (int x : nums) {
            int i = (x - lo) / size;
            buckets[i][0] = Math.min(buckets[i][0], x);
            buckets[i][1] = Math.max(buckets[i][1], x);
        }
        int ans = 0, prev = lo;
        for (int[] b : buckets) {
            if (b[0] == Integer.MAX_VALUE) continue;
            ans = Math.max(ans, b[0] - prev); prev = b[1];
        }
        return ans;
    }
}

