class Trie:
    def __init__(self): self.root={}
    def insert(self,word):
        node=self.root
        for ch in word: node=node.setdefault(ch,{})
        node['#']=True
    def search(self,word):
        node=self._find(word); return bool(node and node.get('#'))
    def starts_with(self,prefix): return bool(self._find(prefix))
    def _find(self,s):
        node=self.root
        for ch in s:
            if ch not in node:return None
            node=node[ch]
        return node

class Trie {
