}

class WordDictionary:
    def __init__(self): self.root={}
    def add_word(self,word):
        node=self.root
        for ch in word: node=node.setdefault(ch,{})
        node['#']=True
    def search(self,word): return self._dfs(word,0,self.root)
    def _dfs(self,word,i,node):
        if i==len(word): return '#' in node
        ch=word[i]
        if ch!='.': return ch in node and self._dfs(word,i+1,node[ch])
        return any(self._dfs(word,i+1,node[c]) for c in node if c!='#')

class WordDictionary {
    private WordDictionary[] children=new WordDictionary[26]; private boolean end;
    public void addWord(String word){WordDictionary node=this;for(char c:word.toCharArray()){int i=c-'a';if(node.children[i]==null)node.children[i]=new WordDictionary();node=node.children[i];}node.end=true;}
    public boolean search(String word){return dfs(word,0,this);}
    private boolean dfs(String word,int i,WordDictionary node){
        if(i==word.length())return node.end;
        char c=word.charAt(i);
        if(c!='.') return node.children[c-'a']!=null&&dfs(word,i+1,node.children[c-'a']);
        for(WordDictionary child:node.children) if(child!=null&&dfs(word,i+1,child)) return true;
        return false;
    }
}

def find_words(board,words):
    root={}
