    ans=set(); m,n=len(board),len(board[0])
    def dfs(i,j,node):
        ch=board[i][j]
        if ch not in node:return
        node=node[ch]
        if '#' in node: ans.add(node['#'])
        board[i][j]='#'
        for a,b in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=a<m and 0<=b<n: dfs(a,b,node)
        board[i][j]=ch
    for i in range(m):
        for j in range(n): dfs(i,j,root)
    return sorted(ans)

import java.util.*;
class Solution {
    public List<String> findWords(char[][] board, String[] words) {
