        if(next.word!=null){ans.add(next.word);next.word=null;}
        b[i][j]='#'; int[][] d={{1,0},{-1,0},{0,1},{0,-1}};
        for(int[] p:d){int a=i+p[0],k=j+p[1];if(a>=0&&a<b.length&&k>=0&&k<b[0].length&&b[a][k]!='#')dfs(b,a,k,next,ans);}
        b[i][j]=c;
    }
    class TrieNode{String word;TrieNode[] children=new TrieNode[26];}
}

class Solution:
    def replace_words(self,dictionary,sentence):
        root={}
