def find_maximum_xor(nums):
    root={}; ans=0
    def insert(x):
        node=root
        for i in range(31,-1,-1):
            b=(x>>i)&1; node=node.setdefault(b,{})
    def query(x):
        node=root; ans=0
        for i in range(31,-1,-1):
            b=(x>>i)&1
            if 1-b in node: ans|=1<<i; node=node[1-b]
            else: node=node[b]
        return ans
