def count_smaller(nums):
    ranks={v:i+1 for i,v in enumerate(sorted(set(nums)))}; m=len(ranks); tree=[0]*(m+1); ans=[]
    def update(i):
        while i<=m: tree[i]+=1; i+=i&-i
    def query(i):
        s=0
