        for(int x:sorted)if(!rank.containsKey(x))rank.put(x,++m);
        tree=new int[m+1];java.util.List<Integer> ans=new java.util.ArrayList<>();
        for(int i=nums.length-1;i>=0;i--){int r=rank.get(nums[i]);ans.add(query(r-1));update(r);}
