def knapsack_bound(items,capacity):
    items=sorted(items,key=lambda x:x[1]/x[0],reverse=True); n=len(items); best=0
    def bound(i,value,left):
        total=value
        for w,v in items[i:]:
            if w<=left:total+=v;left-=w
            else:total+=v*left/w; break
        return total
    def dfs(i,value,left):
        nonlocal best
        if i==n or left==0:best=max(best,value);return
        if bound(i,value,left)<=best:return
        w,v=items[i]
        if w<=left:dfs(i+1,value+v,left-w)
        dfs(i+1,value,left)
    dfs(0,0,capacity);return best

