    }
    private double bound(int i,int value,int left){double total=value;for(;i<items.length;i++){int w=items[i][0],v=items[i][1];if(w<=left){total+=v;left-=w;}else{total+=(double)v*left/w;break;}}return total;}
    private void dfs(int i,int value,int left){if(i==items.length||left==0){best=Math.max(best,value);return;}if(bound(i,value,left)<=best)return;int w=items[i][0],v=items[i][1];if(w<=left)dfs(i+1,value+v,left-w);dfs(i+1,value,left);}
}

def traveling_salesman(cost):
    n=len(cost); full=(1<<n)-1; dp=[[float('inf')]*n for _ in range(1<<n)]; dp[1][0]=0
    for mask in range(1<<n):
        if not mask&1:continue
        for last in range(n):
            if not mask>>last&1 or dp[mask][last]==float('inf'):continue
            for nxt in range(n):
                if not mask>>nxt&1:
                    nmask=mask|1<<nxt;dp[nmask][nxt]=min(dp[nmask][nxt],dp[mask][last]+cost[last][nxt])
    ans=min(dp[full][i]+cost[i][0] for i in range(1,n) if dp[full][i]<float('inf'))
    return int(ans) if ans<float('inf') else -1

import java.util.*;
class Solution {
    public int travelingSalesman(int[][] cost){int n=cost.length,full=(1<<n)-1;long[][] dp=new long[1<<n][n];for(long[] row:dp)Arrays.fill(row,Long.MAX_VALUE);dp[1][0]=0L;
        for(int mask=1;mask<=full;mask++){if((mask&1)==0)continue;for(int last=0;last<n;last++){if((mask>>last&1)==0||dp[mask][last]==Long.MAX_VALUE)continue;for(int next=0;next<n;next++){if((mask>>next&1)!=0)continue;int nm=mask|1<<next;dp[nm][next]=Math.min(dp[nm][next],dp[mask][last]+cost[last][next]);}}}
        long ans=Long.MAX_VALUE;for(int i=1;i<n;i++)if(dp[full][i]<Long.MAX_VALUE)ans=Math.min(ans,dp[full][i]+cost[i][0]);return ans==Long.MAX_VALUE?-1:(int)ans;
    }
}

def split_array(nums,k):
    lo,hi=max(nums),sum(nums)
    def feasible(limit):
        count=1; total=0
        for x in nums:
            if total+x>limit:count+=1;total=x
            else:total+=x
        return count<=k
    while lo<hi:
        mid=(lo+hi)//2
        if feasible(mid):hi=mid
        else:lo=mid+1
    return lo

class Solution {
    public long splitArray(int[] nums,int k){long lo=0,hi=0;for(int x:nums){lo=Math.max(lo,x);hi+=x;}
        while(lo<hi){long mid=lo+(hi-lo)/2;if(feasible(nums,k,mid))hi=mid;else lo=mid+1;}return lo;}
    private boolean feasible(int[] nums,int k,long limit){int count=1;long total=0;for(int x:nums){if(total+x>limit){count++;total=x;}else total+=x;}return count<=k;}
}

def matrix_to_adj(matrix):
    n=len(matrix); adj=[[] for _ in range(n)]
    for i,row in enumerate(matrix):
        for j,w in enumerate(row):
            if w!=0:adj[i].append((j,w))
    return adj

import java.util.*;
class Solution {
    public List<List<int[]>> matrixToAdj(int[][] matrix){int n=matrix.length;List<List<int[]>> adj=new ArrayList<>();for(int i=0;i<n;i++)adj.add(new ArrayList<>());
        for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(matrix[i][j]!=0)adj.get(i).add(new int[]{j,matrix[i][j]});return adj;
    }
}

from collections import defaultdict
def reachable(n,edges,source,target):
    if source==target:return True
    g=defaultdict(list)
    for u,v in edges:g[u].append(v)
    seen={source}; stack=[source]
    while stack:
        u=stack.pop()
        for v in g[u]:
            if v==target:return True
            if v not in seen:seen.add(v);stack.append(v)
    return False

import java.util.*;
class Solution {
    public boolean reachable(int n,int[][] edges,int source,int target){
        if(source==target)return true;List<List<Integer>> g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new ArrayList<>());for(int[] e:edges)g.get(e[0]).add(e[1]);
        boolean[] seen=new boolean[n];Deque<Integer> stack=new ArrayDeque<>();stack.push(source);seen[source]=true;
        while(!stack.isEmpty()){int u=stack.pop();for(int v:g.get(u)){if(v==target)return true;if(!seen[v]){seen[v]=true;stack.push(v);}}}return false;
    }
}

from collections import defaultdict
def nodes_reaching(n,edges,target):
    rg=defaultdict(list)
    for u,v in edges:rg[v].append(u)
    seen={target}; stack=[target]
    while stack:
        u=stack.pop()
        for v in rg[u]:
            if v not in seen:seen.add(v);stack.append(v)
    return sorted(seen)

import java.util.*;
class Solution {
    public List<Integer> nodesReaching(int n,int[][] edges,int target){
        List<List<Integer>> rg=new ArrayList<>();for(int i=0;i<n;i++)rg.add(new ArrayList<>());for(int[] e:edges)rg.get(e[1]).add(e[0]);
        boolean[] seen=new boolean[n];Deque<Integer> stack=new ArrayDeque<>();stack.push(target);seen[target]=true;List<Integer> ans=new ArrayList<>();
        while(!stack.isEmpty()){int u=stack.pop();ans.add(u);for(int v:rg.get(u))if(!seen[v]){seen[v]=true;stack.push(v);}}
        java.util.Collections.sort(ans);return ans;
    }
}

def grid_edge_count(grid):
    m,n=len(grid),len(grid[0]); ans=0
    for i in range(m):
        for j in range(n):
            if grid[i][j]==1:
                if i+1<m and grid[i+1][j]==1:ans+=1
                if j+1<n and grid[i][j+1]==1:ans+=1
    return ans

class Solution {
    public int gridEdgeCount(int[][] grid){int m=grid.length,n=grid[0].length,ans=0;
        for(int i=0;i<m;i++)for(int j=0;j<n;j++)if(grid[i][j]==1){if(i+1<m&&grid[i+1][j]==1)ans++;if(j+1<n&&grid[i][j+1]==1)ans++;}return ans;
    }
}
